import React, { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import {
  initialLists,
  CURRENT_USER_ID,
  CURRENT_USER_NAME,
} from "../data/mockData";

function ShoppingListDetail() {
  // 1. ZÍSKÁNÍ ID Z URL
  // Pomocí hooku `useParams` si z URL vezmeme parametr `:listId`
  const { listId } = useParams();

  // 2. STAVY KOMPONENTY
  // Stav pro data celého seznamu.
  const [list, setList] = useState(null);
  // Stav pro text v inputu pro novou položku
  const [newItemName, setNewItemName] = useState("");
  // Stav pro filtr (co zobrazujeme - 'unresolved' nebo 'all')
  const [filter, setFilter] = useState("unresolved");

  // 3. NAČTENÍ DAT
  // Tento `useEffect` se spustí jen jednou při načtení komponenty.
  // Najde v našich datech ten správný seznam podle `listId` z URL.
  useEffect(() => {
    // POZOR: v reálné aplikaci by zde bylo volání na server (fetch)
    // My jen simulujeme nalezení dat v naší konstantě.
    const foundList = initialLists.find((l) => l.id === listId);
    setList(foundList);
    // Všimni si, že data dáváme do STAVU (`setList`),
    // abychom je mohli během používání stránky měnit (přidávat položky atd.)
  }, [listId]); // Spustí se znovu, jen pokud se změní listId

  // --- FUNKCE PRO ÚPRAVU SEZNAMU ---

  // Přidání nové položky
  const handleAddItem = (e) => {
    e.preventDefault(); // Zabráníme odeslání formuláře (reloadu stránky)
    if (newItemName.trim() === "") return; // Ignorujeme prázdný vstup

    const newItem = {
      id: `item-${Date.now()}`,
      name: newItemName,
      solved: false,
    };

    // Aktualizujeme stav: vezmeme starý seznam a přidáme novou položku do 'items'
    setList({
      ...list,
      items: [...list.items, newItem],
    });

    setNewItemName(""); // Vyčistíme input
  };

  // Označení položky jako vyřešené
  const handleMarkSolved = (itemId) => {
    setList({
      ...list,
      items: list.items.map((item) =>
        item.id === itemId ? { ...item, solved: true } : item
      ),
    });
  };

  // Smazání položky
  const handleDeleteItem = (itemId) => {
    setList({
      ...list,
      items: list.items.filter((item) => item.id !== itemId),
    });
  };

  // Změna názvu seznamu (jen pro vlastníka)
  const handleChangeName = () => {
    const newName = prompt("Zadejte nový název seznamu:", list.name);
    if (newName && newName.trim() !== "") {
      setList({ ...list, name: newName });
    }
  };

  // --- POMOCNÉ VÝPOČTY PŘED RENDEREM ---

  // Pokud se seznam ještě nenačetl (nebo neexistuje), zobrazíme "Načítání..."
  if (!list) {
    return <div className="content">Hledám seznam...</div>;
  }

  // Zjistíme, zda je přihlášený uživatel vlastníkem
  const isOwner = list.owner === CURRENT_USER_ID;

  // Filtrujeme položky podle aktuálního filtru
  const filteredItems = list.items.filter((item) => {
    if (filter === "unresolved") {
      return !item.solved; // Zobrazíme jen nevyřešené
    }
    return true; // Jinak (při 'all') zobrazíme všechny
  });

  // --- RENDER KOMPONENTY ---

  return (
    <>
      {/* Hlavička s navigací zpět a názvem seznamu */}
      <div className="header" style={{ justifyContent: "flex-start", gap: "20px" }}>
        <Link to="/" className="button button-secondary">
          &larr; Back
        </Link>
        <h2>{list.name}</h2>
        {/* Tlačítko pro změnu názvu vidí jen vlastník */}
        {isOwner && (
          <button className="button-secondary" onClick={handleChangeName}>
            Change
          </button>
        )}
        <button className="button-secondary" style={{ marginLeft: "auto" }}>
          Show members
        </button>
      </div>

      <div className="content">
        {/* Formulář pro přidání položky */}
        <form className="add-item-form" onSubmit={handleAddItem}>
          <input
            type="text"
            placeholder="Enter item name..."
            value={newItemName}
            onChange={(e) => setNewItemName(e.target.value)}
          />
          <button type="submit" className="button-primary">
            + Add Item
          </button>
        </form>

        {/* Hlavička seznamu položek s filtry */}
        <div className="item-list-header">
          <h3>List of Items ({filteredItems.length})</h3>
          <div className="tabs">
            <button
              className={`tab-button ${filter === "unresolved" ? "active" : ""}`}
              onClick={() => setFilter("unresolved")}
            >
              Unresolved only
            </button>
            <button
              className={`tab-button ${filter === "all" ? "active" : ""}`}
              onClick={() => setFilter("all")}
            >
              Show all
            </button>
          </div>
        </div>

        {/* Seznam položek */}
        <div className="item-list">
          {filteredItems.map((item) => (
            <div
              key={item.id}
              className={`item-row ${item.solved ? "solved" : ""}`}
            >
              <span>{item.name}</span>
              <div className="item-row-actions">
                {/* Tlačítko "Mark solved" zobrazíme, jen pokud položka NENÍ vyřešená */}
                {!item.solved && (
                  <button
                    className="button-secondary"
                    onClick={() => handleMarkSolved(item.id)}
                  >
                    ✓ Mark solved
                  </button>
                )}
                <button
                  className="button-danger"
                  onClick={() => handleDeleteItem(item.id)}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </>
  );
}

export default ShoppingListDetail;
